  fun ms' => exists a3 m',
    ms' = MS (mkR (Z_to_bv 64 P_CRS_RET1) (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2
                  s0 (Z_to_bv 64 own) (Z_to_bv 64 allocb) (Z_to_bv 64 64) (Z_to_bv 64 8) a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_ALLOCIMPL_ALLOCATE) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -48)
    /\ rw_cells usegs m' (bv_unsigned sp + -48) [C8 (Z_to_bv 64 allocb); C8 s1; C8 s0; C8 (Z_to_bv 64 0x38f1c); C8 (Z_to_bv 64 allocb); C8 ra].
