  ro_cells usegs m ctx [C8 (wz allocb)] -> bv_unsigned sp <= ctx -> ctx + 8 <= 2^64 ->
  rw_cells usegs m allocb [C8 (wz VP_ALLOCIMPL); CB 8 jal] -> XStatics m ->
  stk usegs m lo (bv_unsigned sp) -> lo + 48 <= bv_unsigned sp -> hceil <= lo ->
  allocb + SZ_ALLOCIMPL <= lo ->
  0 <= own < 2^64 -> 0 < own -> own mod 8 = 0 -> 0 < allocb -> allocb mod 8 = 0 ->                    (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (crs_segA_post sp gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc own allocb lo ra s0 s1 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 ctx) (Z_to_bv 64 own) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_CREATE_SSVC) fc None m (seg_rom usegs)).
