(* [comment removed for export] *)
Definition crs_segC_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (v own lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (v, v + 48)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' v (SvcHdrCells (ssvc_hdr0 own)).

Lemma crs_segC : forall sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (v own allocb lo : Z) (ra s0 s1 rax : word),
  rw_cells usegs m (bv_unsigned sp + -48) [C8 (Z_to_bv 64 allocb); C8 s1; C8 s0; C8 (Z_to_bv 64 0x38f1c); C8 (Z_to_bv 64 allocb); C8 ra] ->
  rw_cells usegs m v (SvcHdrCells (mkSVC VP_SSVC 0 0 own 0 0)) ->
  stk usegs m lo (bv_unsigned sp + -48) -> lo + 48 <= bv_unsigned sp -> hceil <= lo ->
  v + 48 <= lo -> 0 < v -> 0 <= own < 2^64 ->
  bv_unsigned ra mod 2 = 0 ->
  v mod 8 = 0 -> 0 <= allocb < 2^64 ->                                                                (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (crs_segC_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F fc v own lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (Z_to_bv 64 v) (Z_to_bv 64 own) a0 a1 a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_CRS_RET2) fc None m (seg_rom usegs)).
